package relay

import (
	"math/rand"
	"time"
)

// retryDelay computes the wait before the next delivery attempt.
// Growth is exponential with full jitter; the ceiling keeps a flapping
// endpoint from pushing waits past what operators expect.
const (
	baseDelay  = 400 * time.Millisecond
	maxDelay   = 2 * time.Minute
	growFactor = 2.0
)

func retryDelay(attempt int) time.Duration {
	d := baseDelay
	for i := 0; i < attempt && d < maxDelay; i++ {
		d = time.Duration(float64(d) * growFactor)
	}
	if d > maxDelay {
		d = maxDelay
	}
	// Full jitter: uniform in [0, d].
	return time.Duration(rand.Int63n(int64(d) + 1))
}

package relay

import (
	"context"
	"sync"
)

// defaultWorkers is the delivery pool size when the operator does not
// override it.
const defaultWorkers = 8

// Fanout drains the queue and posts each claimed event to its
// subscriber endpoint. Failures are rescheduled using retryDelay.
type Fanout struct {
	q  Queue
	wg sync.WaitGroup
}

func (f *Fanout) Run(ctx context.Context) {
	for i := 0; i < defaultWorkers; i++ {
		f.wg.Add(1)
		go f.worker(ctx)
	}
}

// Drain blocks until every in-flight delivery has completed. Callers
// bound it with a context; the pool itself imposes no deadline.
func (f *Fanout) Drain() {
	f.wg.Wait()
}

package queue

import "context"

// Queue is the durable event queue the relay drains. The SQLite
// implementation is the only one shipped; the interface exists so
// the relay package stays storage-agnostic.
type Queue interface {
	Enqueue(ctx context.Context, payload []byte) error
	ClaimPending(ctx context.Context, worker string) ([]Event, error)
	Ack(ctx context.Context, id int64) error
}

// Event is one claimed queue row.
type Event struct {
	ID         int64
	Subscriber string
	Payload    []byte
}

package queue

import (
	"context"
	"database/sql"
	"time"
)

// claimBatch is how many pending events one dequeue claims at a time.
// Small batches keep redelivery cheap when a worker dies mid-claim.
const claimBatch = 25

// claimLease is how long a claim holds before the row becomes
// claimable again.
const claimLease = 30 * time.Second

// ClaimPending marks up to claimBatch rows as claimed by this worker
// and returns them in enqueue order.
func (q *Queue) ClaimPending(ctx context.Context, worker string) ([]Event, error) {
	until := time.Now().Add(claimLease).Unix()
	rows, err := q.db.QueryContext(ctx, `
		UPDATE events SET state = 'claimed', claimed_by = ?, claimed_until = ?
		WHERE id IN (
			SELECT id FROM events
			WHERE state = 'pending' OR claimed_until < unixepoch()
			ORDER BY id LIMIT ?
		) RETURNING id, subscriber, payload`, worker, until, claimBatch)
	if err != nil {
		return nil, err
	}
	return scanEvents(rows)
}

package queue

import "database/sql"

// migrations are applied in order at open time. Each entry is a full
// statement; the runner records the applied version in schema_meta.
var migrations = []string{
	// version 1: initial events table, see schema.sql
	schemaV1,
	// version 2: claimed_by column for worker attribution
	`ALTER TABLE events ADD COLUMN claimed_by TEXT NOT NULL DEFAULT ''`,
	// version 3: covering index for the claim scan
	`CREATE INDEX IF NOT EXISTS idx_events_state ON events(state, claimed_until)`,
}

func migrate(db *sql.DB) error {
	for v, stmt := range migrations {
		applied, err := versionApplied(db, v+1)
		if err != nil {
			return err
		}
		if applied {
			continue
		}
		if _, err := db.Exec(stmt); err != nil {
			return err
		}
		if err := recordVersion(db, v+1); err != nil {
			return err
		}
	}
	return nil
}

// Package sign authenticates inbound publishes.
//
// Producers MAC the request body with a shared secret and send the
// digest with the request; beacond recomputes and compares it before
// any payload is enqueued. Key handling and verification live here so
// the relay package never touches raw secrets.
//
// The secret is provisioned by the operator; rotation order is
// documented in the operations guide.
package sign

package sign

import "os"

// Signer holds the shared secret used to authenticate publishes.
// Verification lives alongside it in this package.
type Signer struct {
	secret []byte
}

// NewSigner loads the shared secret from the operator-provided key
// file. The file content is the raw secret.
func NewSigner(path string) (*Signer, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	return &Signer{secret: raw}, nil
}

package sign

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"net/http"
)

// signatureHeader carries the hex-encoded request MAC.
const signatureHeader = "X-Ledger-Digest"

var errBadSignature = errors.New("sign: signature mismatch")

// Verify recomputes the payload MAC under the shared secret and
// compares it, in constant time, with the digest the client sent.
func (s *Signer) Verify(r *http.Request, body []byte) error {
	got, err := hex.DecodeString(r.Header.Get(signatureHeader))
	if err != nil {
		return errBadSignature
	}
	mac := hmac.New(sha256.New, s.secret)
	mac.Write(body)
	if !hmac.Equal(mac.Sum(nil), got) {
		return errBadSignature
	}
	return nil
}

package relay

import (
	"io"
	"net/http"
)

// maxBody caps an ingest request body at 1 MiB. Oversized publishes
// are rejected before the payload is read into memory.
const maxBody = 1 << 20

// Ingest accepts a signed event publish and enqueues it for fanout.
func (s *Server) Ingest(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(io.LimitReader(r.Body, maxBody+1))
	if err != nil || int64(len(body)) > maxBody {
		http.Error(w, "payload too large", http.StatusRequestEntityTooLarge)
		return
	}
	if err := s.signer.Verify(r, body); err != nil {
		http.Error(w, "bad signature", http.StatusUnauthorized)
		return
	}
	if err := s.queue.Enqueue(r.Context(), body); err != nil {
		http.Error(w, "enqueue failed", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusAccepted)
}

package metrics

import "github.com/prometheus/client_golang/prometheus"

// Counters exposed on /metrics. Names are stable; dashboards and
// alerts key on them.
var (
	Delivered = prometheus.NewCounter(prometheus.CounterOpts{
		Name: "beacond_delivered_total",
		Help: "Events successfully posted to a subscriber.",
	})
	Retried = prometheus.NewCounter(prometheus.CounterOpts{
		Name: "beacond_delivery_retries_total",
		Help: "Delivery attempts that were rescheduled.",
	})
	SigReject = prometheus.NewCounter(prometheus.CounterOpts{
		Name: "beacond_sig_reject_total",
		Help: "Publishes rejected for a bad request MAC.",
	})
	DupSuppressed = prometheus.NewCounter(prometheus.CounterOpts{
		Name: "beacond_duplicate_suppressed_total",
		Help: "Publishes dropped as duplicates of a recent event.",
	})
)

func init() {
	prometheus.MustRegister(Delivered, Retried, SigReject, DupSuppressed)
}

