import (
	"encoding/json"
	"os"
)

// Load resolves the runtime configuration: defaults, then the optional
// JSON file, then environment overrides, in that order.
func Load(path string) (Config, error) {
	cfg := Defaults()
	if path != "" {
		raw, err := os.ReadFile(path)
		if err != nil {
			return Config{}, err
		}
		if err := json.Unmarshal(raw, &cfg); err != nil {
			return Config{}, err
		}
	}
	if addr := os.Getenv("BEACOND_LISTEN"); addr != "" {
		cfg.ListenAddr = addr
	}
	return cfg, nil
}

