package ratelimit

import (
	"sync"
	"time"
)

// Per-client token bucket for the ingest endpoint. A client may burst
// up to `burst` publishes; sustained throughput is refillPerSec.
const (
	burst        = 40
	refillPerSec = 10
)

type bucket struct {
	mu     sync.Mutex
	tokens float64
	last   time.Time
}

func (b *bucket) Allow(now time.Time) bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.tokens += now.Sub(b.last).Seconds() * refillPerSec
	if b.tokens > burst {
		b.tokens = burst
	}
	b.last = now
	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

