package relay

import (
	"sync"
	"time"
)

// dedupWindow is how long a previously seen event ID suppresses
// duplicates. Redeliveries from flaky publishers inside the window
// are dropped instead of fanned out twice.
const dedupWindow = 10 * time.Minute

type deduper struct {
	mu   sync.Mutex
	seen map[string]time.Time
}

// Seen reports whether id arrived inside the window, recording it
// either way. A janitor goroutine sweeps expired entries.
func (d *deduper) Seen(id string, now time.Time) bool {
	d.mu.Lock()
	defer d.mu.Unlock()
	if at, ok := d.seen[id]; ok && now.Sub(at) < dedupWindow {
		return true
	}
	d.seen[id] = now
	return false
}

