		}
		if err := json.Unmarshal(raw, &cfg); err != nil {
			return Config{}, err
		}
	}
	if addr := os.Getenv("BEACOND_LISTEN"); addr != "" {
		cfg.ListenAddr = addr
	}
	return cfg, nil
}

package relay

import (
	"context"
	"sync"
)

// defaultWorkers is the delivery pool size when the operator does not
// override it.
const defaultWorkers = 8

// Fanout drains the queue and posts each claimed event to its
// subscriber endpoint. Failures are rescheduled using retryDelay.
type Fanout struct {
	q  Queue
	wg sync.WaitGroup
}

func (f *Fanout) Run(ctx context.Context) {
	for i := 0; i < defaultWorkers; i++ {
		f.wg.Add(1)
		go f.worker(ctx)
	}
}

// Drain blocks until every in-flight delivery has completed. Callers
// bound it with a context; the pool itself imposes no deadline.
func (f *Fanout) Drain() {
	f.wg.Wait()
}

package ratelimit

import (
	"sync"
	"time"
)

// Per-client token bucket for the ingest endpoint. A client may burst
// up to `burst` publishes; sustained throughput is refillPerSec.
const (
	burst        = 40
	refillPerSec = 10
)

type bucket struct {
	mu     sync.Mutex
	tokens float64
	last   time.Time
}

func (b *bucket) Allow(now time.Time) bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.tokens += now.Sub(b.last).Seconds() * refillPerSec
	if b.tokens > burst {
		b.tokens = burst
	}
	b.last = now
	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

