// claimBatch is how many pending events one dequeue claims at a time.
// Small batches keep redelivery cheap when a worker dies mid-claim.
const claimBatch = 25

// claimLease is how long a claim holds before the row becomes
// claimable again.
const claimLease = 30 * time.Second

// ClaimPending marks up to claimBatch rows as claimed by this worker
// and returns them in enqueue order.
func (q *Queue) ClaimPending(ctx context.Context, worker string) ([]Event, error) {
	until := time.Now().Add(claimLease).Unix()
	rows, err := q.db.QueryContext(ctx, `
		UPDATE events SET state = 'claimed', claimed_by = ?, claimed_until = ?
		WHERE id IN (
			SELECT id FROM events
			WHERE state = 'pending' OR claimed_until < unixepoch()
			ORDER BY id LIMIT ?
		) RETURNING id, subscriber, payload`, worker, until, claimBatch)
	if err != nil {
		return nil, err
	}
	return scanEvents(rows)
}

